INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(1,1,N'Parcel delivery verification',N'SMS',N'Parcel Support Example',1);
INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(2,2,N'Marketplace bargain chat',N'WhatsApp',N'Kedai Contoh Demo',1);
INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(3,3,N'Guaranteed investment invitation',N'Email',N'Pelaburan Contoh Demo',1);
INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(4,4,N'Loan release phone call',N'Call',N'Pegawai Pinjaman Contoh',1);
INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(5,5,N'Account suspension email',N'Email',N'Bank Contoh Demo',1);
INSERT INTO Scenarios(ScenarioID,CategoryID,Title,Channel,SenderName,IsPublished) VALUES(6,6,N'Emergency request from an online partner',N'WhatsApp',N'Kenalan Contoh Maya',1);
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(1,1,1,N'Salam, terdapat makluman mengenai bungkusan anda.',0,N'A greeting and reference to a parcel do not, by themselves, establish authenticity.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(2,1,2,N'Bungkusan anda akan dibatalkan dalam 10 minit jika tidak bertindak sekarang.',1,N'An immediate deadline pressures the recipient to act before checking.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(3,1,3,N'Sahkan penghantaran melalui https://parcel-confirm.invalid.',1,N'An unexpected verification link should not be used to provide personal or banking details.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(4,1,4,N'Masukkan kata laluan bank anda untuk mengesahkan alamat.',1,N'A request for a banking password is unrelated to confirming a delivery address.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(5,1,5,N'Berikan OTP kepada pegawai penghantaran kami.',1,N'Do not disclose an authentication code to a message sender or caller.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(6,1,6,N'Rujukan contoh: DEMO-PARCEL-01.',0,N'A reference label can be invented. It neither proves nor disproves the claim.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(7,2,1,N'Hai, telefon terpakai itu masih tersedia.',0,N'A normal product enquiry is not a warning sign by itself.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(8,2,2,N'Bayar terus di luar platform supaya pembelian ini tidak direkodkan.',1,N'Moving a transaction outside the platform removes visibility and may remove safeguards.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(9,2,3,N'Jangan semak dengan khidmat pelanggan platform.',1,N'Discouraging independent verification is suspicious.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(10,2,4,N'Hantar OTP bank supaya saya boleh terima bayaran.',1,N'A seller should not need your bank authentication code.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(11,2,5,N'Harga ini tamat dalam lima minit, pindah wang sekarang.',1,N'Artificial urgency can push a buyer into an unchecked transfer.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(12,2,6,N'Warna yang ditawarkan ialah biru.',0,N'A product colour is ordinary descriptive information, not proof that the seller is genuine.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(13,3,1,N'Subject: Jemputan taklimat pelaburan',0,N'An invitation subject alone is not enough to assess legitimacy.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(14,3,2,N'Pulangan 30% sehari dijamin tanpa sebarang risiko.',1,N'Guaranteed extraordinary returns with no risk are a major warning sign.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(15,3,3,N'Logo rasmi kami bermakna anda tidak perlu menyemak dengan pengawal selia.',1,N'A copied logo cannot replace an independent authorisation check.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(16,3,4,N'Pindahkan deposit sebelum jam 12 supaya slot anda tidak hilang.',1,N'A short payment deadline can prevent careful evaluation.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(17,3,5,N'Bayar yuran tambahan untuk membuka keuntungan yang belum boleh dikeluarkan.',1,N'A demand for more money to release supposed profits may extend the loss.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(18,3,6,N'Salam hormat, Pasukan Contoh.',0,N'A polite closing says nothing reliable about investment authorisation.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(19,4,1,N'Caller: Selamat petang, saya ingin bercakap tentang permohonan pinjaman.',0,N'A greeting and an application reference alone do not verify the caller.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(20,4,2,N'Caller: Pinjaman dijamin lulus tanpa semakan apa-apa maklumat.',1,N'An unverified guarantee should prompt independent checks.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(21,4,3,N'Caller: Bayar yuran pelepasan dahulu sebelum wang boleh dipindahkan.',1,N'An advance fee for a promised loan is a warning sign in this unverified offer.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(22,4,4,N'Caller: Saya perlukan kata laluan perbankan anda untuk proses ini.',1,N'Never disclose a banking password to a caller.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(23,4,5,N'Caller: Jangan hubungi bank; terus bayar dalam lima minit.',1,N'Blocking verification while demanding immediate payment is suspicious.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(24,4,6,N'Caller: Rujukan panggilan ialah DEMO-LOAN-04.',0,N'An invented reference can make a call sound credible but does not authenticate it.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(25,5,1,N'Subject: Makluman akaun pelanggan',0,N'A generic account subject is not sufficient to establish authenticity.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(26,5,2,N'Akaun anda dibekukan. Log masuk di https://bank-secure.invalid sekarang.',1,N'A threatening message linked to an unfamiliar login page needs independent verification.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(27,5,3,N'Balas e-mel ini dengan nama pengguna dan kata laluan anda.',1,N'Passwords should not be provided in response to an email request.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(28,5,4,N'Pasang fail APK yang kami lampirkan dan benarkan semua akses.',1,N'An unsolicited installation and broad permissions can expose the device.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(29,5,5,N'Hantar TAC kepada kami untuk membatalkan transaksi.',1,N'Do not disclose transaction authentication codes to an email sender.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(30,5,6,N'Terima kasih, Pasukan Sokongan Contoh.',0,N'A support signature can be imitated and does not verify the sender.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(31,6,1,N'Hai, bagaimana hari awak?',0,N'An ordinary greeting is not suspicious by itself.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(32,6,2,N'Kita baru kenal tetapi saya sayang awak; buktikan dengan menghantar wang.',1,N'A rapid declaration combined with a demand for money creates emotional pressure.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(33,6,3,N'Kamera saya sentiasa rosak, jadi saya tidak akan buat panggilan video.',1,N'Repeatedly avoiding identity checks leaves the claimed identity unverified.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(34,6,4,N'Jangan ceritakan permintaan wang ini kepada keluarga atau kawan.',1,N'Secrecy discourages outside advice and can isolate the recipient.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(35,6,5,N'Hadiah saya ditahan. Bayar caj segera melalui pautan https://gift-release.invalid.',1,N'An unexpected gift and urgent release fee can be used to obtain money.');
INSERT INTO ScenarioParts(PartID,ScenarioID,PartOrder,PartText,IsRedFlag,Explanation) VALUES(36,6,6,N'Kita boleh berbual lagi esok.',0,N'An ordinary closing is neutral; it does not make the surrounding requests safe.');
