-- Member 3. Run after 05_Seed_Quizzes.sql on a fresh development database.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF EXISTS(SELECT 1 FROM Scenarios) OR EXISTS(SELECT 1 FROM ScenarioParts)
BEGIN ROLLBACK; THROW 51000, 'Scenario seed requires empty scenario tables. Use the agreed full rebuild sequence.', 1; END;
SET IDENTITY_INSERT Scenarios ON;
SET IDENTITY_INSERT Scenarios OFF;
SET IDENTITY_INSERT ScenarioParts ON;
SET IDENTITY_INSERT ScenarioParts OFF;
COMMIT;
